//! Byte-exact replay of the recorded legacy cipher vectors.
//!
//! `data/vectors.rs` is generated by `reference/itzencrypt_ref.py` from
//! `reference/ground_truth.json`, which the C++ harness in `reference/`
//! produced by linking the **byte-for-byte unmodified** `ITZEncrypt.cpp`.
//! Nothing here was derived from this crate's own implementation, so a
//! disagreement means the port is wrong, not that the fixture moved.
//!
//! `SENTINEL` matters: the legacy `Decode` never writes output offset 2, so the
//! recorded output reflects whatever the caller's destination already held.

#[path = "data/vectors.rs"]
mod vectors_data;

use gz_cipher::{Cipher, CipherError};
use vectors_data::CASES;

/// Fill the legacy harness used for its destination buffers.
const SENTINEL: u8 = 0xAA;

fn unhex(hex: &str) -> Vec<u8> {
    assert!(hex.len().is_multiple_of(2), "odd-length hex {hex:?}");
    hex.as_bytes()
        .chunks(2)
        .map(|pair| {
            let text = std::str::from_utf8(pair).expect("hex is ascii");
            u8::from_str_radix(text, 16).expect("hex digit")
        })
        .collect()
}

#[test]
fn every_vector_matches_the_legacy() {
    let mut checked = 0usize;
    for case in CASES {
        // Paired instances: the legacy runs one cipher per link end, and the two
        // counters only stay aligned because each is advanced by every call.
        let mut tx = Cipher::session_cipher(case.key1, case.key2);
        let mut rx = Cipher::session_cipher(case.key1, case.key2);

        let mut last_out: Vec<u8> = Vec::new();
        for (index, op) in case.ops.iter().enumerate() {
            let input = if op.follow {
                last_out.clone()
            } else {
                unhex(op.input)
            };
            let expected = unhex(op.output);
            let where_ = format!("{} op {index}", case.name);

            if op.decode {
                let mut dest = vec![SENTINEL; expected.len()];
                let accepted = rx
                    .decode(&input, &mut dest)
                    .unwrap_or_else(|err| panic!("{where_}: unexpected {err:?}"));
                assert_eq!(accepted, op.accepted, "{where_}: accepted");
                assert_eq!(dest, expected, "{where_}: output");
                last_out = expected;
            } else {
                let out = tx
                    .encode(&input)
                    .unwrap_or_else(|err| panic!("{where_}: unexpected {err:?}"));
                assert_eq!(out, expected, "{where_}: output");
                last_out = out;
            }
            checked += 1;
        }

        // A case that exercises both directions drives two instances, and they
        // must land on the same counter or the round trip could not have
        // verified. Decode-only error cases never touch the sender.
        if case.ops.iter().any(|op| op.decode) && case.ops.iter().any(|op| !op.decode) {
            assert_eq!(
                (tx.key1(), tx.key2()),
                (rx.key1(), rx.key2()),
                "{}: peer counters diverged",
                case.name
            );
        }
    }
    assert!(checked >= 39, "expected the full vector set, ran {checked}");
}

#[test]
fn vectors_cover_the_branches_the_legacy_has() {
    let names: Vec<&str> = CASES.iter().map(|case| case.name).collect();
    for required in [
        "A1_encode_passthrough_size0",
        "A4_encode_passthrough_size3",
        "A5_passthrough_ticks_keys",
        "B1_encode_size4",
        "C1_enc2_encode_size8",
        "C3_enc2_counter_advances",
        "C4_enc2_roundtrip",
        "C7_enc2_roundtrip_burst",
        "D1_encode_wrap_ff",
        "D3_roundtrip_wrap",
        "E2_decode_corrupt_payload",
        "E6_decode_wrong_key",
        "E7_decode_corrupt_checksum_slot",
    ] {
        assert!(
            names.contains(&required),
            "vector set lost the {required} case"
        );
    }
}

/// The 65 KB oversize frame is too large to check in as hex, so it is driven
/// here instead. `ground_truth.json` records the same case as
/// `rejected_oversize`, with no output written.
#[test]
fn oversize_frame_is_rejected_without_writing_output() {
    let mut cipher = Cipher::new();
    let mut dest = [SENTINEL; 8];
    let frame = [0xff, 0xff];
    assert_eq!(
        cipher.decode(&frame, &mut dest),
        Err(CipherError::TooLarge(0xffff))
    );
    assert_eq!(dest, [SENTINEL; 8]);
    assert_eq!((cipher.key1(), cipher.key2()), (1, 1));
}

/// `Encode` has no size ceiling in the legacy, so it will happily build a frame
/// that `Decode` then refuses. Worth pinning: a rewrite that "tidies" this up
/// would accept frames the shipped client/server never send.
#[test]
fn encode_has_no_size_ceiling_but_decode_does() {
    let mut tx = Cipher::new();
    let mut rx = Cipher::new();
    let mut frame = vec![0u8; 65001];
    frame[..2].copy_from_slice(&(65001u16).to_le_bytes());

    let wire = tx
        .encode(&frame)
        .expect("legacy Encode does not check the size");
    assert_eq!(&wire[..2], &65001u16.to_le_bytes());

    let mut dest = vec![SENTINEL; wire.len()];
    assert_eq!(
        rx.decode(&wire, &mut dest),
        Err(CipherError::TooLarge(65001))
    );
}
